// Func007_14_00 is a deterministically generated function
// for the repomap perf fixture; it references Func008_15_00
// so the pagerank/refs step in repomap.Build has real edges
// to walk, not an isolated file per symbol.
func Func007_14_00(a, b int) int {
	if a > b {
		return Func008_15_00(a, b) + a
	}
	return Func008_15_00(b, a) - b
}

